@Test
public void testGeneratePkForDbEntity() throws Exception {
    List<Object> pkList = new ArrayList<Object>();
    int testSize = (pkGenerator instanceof JdbcPkGenerator) ? ((JdbcPkGenerator) pkGenerator).getPkCacheSize() * 2 : 25;
    if (testSize < 25) {
        testSize = 25;
    }
    for (int i = 0; i < testSize; i++) {
        Object pk = pkGenerator.generatePk(node, paintingEntity.getPrimaryKeys().iterator().next());
        assertNotNull(pk);
        assertTrue(pk instanceof Number);
        // check that the number is continuous
        // of course this assumes a single-threaded test
        if (accessStackAdapter.supportsBatchPK() && pkList.size() > 0) {
            Number last = (Number) pkList.get(pkList.size() - 1);
            assertEquals(last.intValue() + 1, ((Number) pk).intValue());
        }
        pkList.add(pk);
    }
}

@Test
public void testCreateTableWithFloatAttributeWithScale() {
    PostgresAdapter adapter = objectFactory.newInstance(PostgresAdapter.class, PostgresAdapter.class.getName());
    DbEntity e = new DbEntity("Test");
    DbAttribute dblPrec = new DbAttribute("dbl1");
    dblPrec.setType(Types.FLOAT);
    dblPrec.setMaxLength(22);
    dblPrec.setScale(12);
    e.addAttribute(dblPrec);
    String sql = adapter.createTable(e);
    // CAY-1363.
    // Postgress don't support notations float(a, b)
    assertTrue(sql.indexOf("float(22)") > 0);
    assertEquals(-1, sql.indexOf("float(22, 12)"));
    assertEquals("CREATE TABLE Test (dbl1 float(22) NULL)", sql);
}

