public void testCalculateToManyFromPath() {
    // assemble fixture....
    DataMap map = new DataMap();
    ObjEntity entity = new ObjEntity("Test");
    map.addObjEntity(entity);
    DbEntity dbEntity1 = new DbEntity("TEST1");
    DbEntity dbEntity2 = new DbEntity("TEST2");
