    tPaintings.insert(22, "painting10", 21, 1, 23);
    List<Object[]> result = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME, Artist.PAINTING_ARRAY.dot(Painting.PAINTING_TITLE)).select(context);
