@Test
public void testTrue() {
    JsonTokenizer tokenizer;
    JsonTokenizer.JsonToken token;
    tokenizer = new JsonTokenizer("true");
    token = tokenizer.nextToken();
    assertEquals(JsonTokenizer.TokenType.TRUE, token.type);
    tokenizer = new JsonTokenizer("TRUE");
